import React, { useState, useEffect } from 'react';
import { useTrackerData } from './hooks/useTrackerData';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import CalendarView from './components/CalendarView';
import Reports from './components/Reports';
import RewardsPanel from './components/RewardsPanel';
import NightReview from './components/NightReview';
import { Bell, ShieldCheck, Sun, Moon, Info } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const {
    currentDay,
    calendarData,
    points,
    streak,
    badges,
    darkMode,
    notificationsEnabled,
    setDarkMode,
    setNotificationsEnabled,
    toggleTask,
    skipTask,
    completeDay,
    currentDayData
  } = useTrackerData();

  const [currentView, setCurrentView] = useState('dashboard');
  const [showNightReviewModal, setShowNightReviewModal] = useState(false);

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(calendarData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `180day_tracker_export_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const renderView = () => {
    return (
      <AnimatePresence mode="wait">
        <motion.div
          key={currentView}
          initial={{ opacity: 0, y: 15, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, scale: 1.02 }}
          transition={{ duration: 0.35, ease: "easeOut" }}
          className="w-full"
        >
          {(() => {
            switch (currentView) {
              case 'dashboard':
                return currentDayData ? (
                  <Dashboard 
                    dayData={currentDayData} 
                    toggleTask={toggleTask} 
                    skipTask={skipTask}
                    currentDay={currentDay}
                  />
                ) : null;
              case 'calendar':
                return <CalendarView 
                  calendarData={calendarData} 
                  currentDay={currentDay}
                  onSelectDay={(day) => console.log("Viewing day:", day)}
                />;
              case 'reports':
                return <Reports calendarData={calendarData} onExport={handleExport} />;
              case 'rewards':
                return <RewardsPanel points={points} streak={streak} unlockedBadges={badges} />;
              case 'settings':
                return (
                  <div className="p-10 max-w-4xl mx-auto space-y-12">
                     <div className="space-y-2">
                       <h2 className="text-sm font-bold tracking-[0.2em] text-blue-500 uppercase">Configuration</h2>
                       <h1 className="text-5xl font-black tracking-tight text-white">App Settings</h1>
                     </div>

                     <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                        <div className="glass-card p-8 space-y-8">
                           <h3 className="text-xl font-bold flex items-center gap-3">
                             <ShieldCheck size={24} className="text-blue-500" /> Core Systems
                           </h3>
                           <div className="space-y-6">
                             <div className="flex items-center justify-between p-5 bg-white/5 rounded-3xl border border-white/5 hover:border-white/10 transition-colors">
                                <div>
                                  <p className="text-md font-bold text-white">Visual Mode</p>
                                  <p className="text-xs text-slate-500 uppercase font-bold tracking-tight">Theme Shift</p>
                                </div>
                                <button 
                                  onClick={() => setDarkMode(!darkMode)}
                                  className="w-12 h-12 flex items-center justify-center rounded-2xl bg-blue-600/10 text-blue-400 hover:scale-105 transition-transform"
                                >
                                  {darkMode ? <Moon size={22} /> : <Sun size={22} />}
                                </button>
                             </div>
                             <div className="flex items-center justify-between p-5 bg-white/5 rounded-3xl border border-white/5 hover:border-white/10 transition-colors">
                                <div>
                                  <p className="text-md font-bold text-white">Browser Notifications</p>
                                  <p className="text-xs text-slate-500 uppercase font-bold tracking-tight">Smart Alerts (6AM, 9PM)</p>
                                </div>
                                <button 
                                  onClick={() => {
                                    if (!notificationsEnabled) {
                                      Notification.requestPermission().then(res => {
                                        if (res === 'granted') setNotificationsEnabled(true);
                                      });
                                    } else {
                                      setNotificationsEnabled(false);
                                    }
                                  }}
                                  className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${notificationsEnabled ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/30' : 'bg-white/5 text-slate-400'}`}
                                >
                                  <Bell size={22} />
                                </button>
                             </div>
                           </div>
                        </div>

                        <div className="glass-card p-8 space-y-8 border-red-500/10 bg-red-600/2 shadow-xl">
                           <h3 className="text-xl font-bold flex items-center gap-3 text-red-100">
                             <Info size={24} className="text-red-500" /> Critical Zone
                           </h3>
                           <div className="space-y-4">
                             <button 
                               onClick={() => {
                                  if(confirm("DANGER: Wiping all 180 days of progress? This can't be undone.")) {
                                    localStorage.removeItem('180dayTracker');
                                    window.location.reload();
                                  }
                               }}
                               className="w-full py-5 rounded-3xl bg-red-600/10 border border-red-500/20 text-red-500 font-bold text-sm hover:bg-red-600/20 transition-all uppercase tracking-widest shadow-lg"
                             >
                               Reset All Progress
                             </button>
                             <p className="text-xs text-slate-500 font-medium px-4 text-center leading-relaxed">
                               Warning: All badges, streaks, points, and 180-day history will be deleted.
                             </p>
                           </div>
                        </div>
                     </div>
                  </div>
                );
              default:
                return null;
            }
          })()}
        </motion.div>
      </AnimatePresence>
    );
  };

  return (
    <div className={`flex min-h-screen ${darkMode ? 'bg-[#020617] text-slate-200' : 'bg-slate-50 text-slate-900'} transition-colors duration-700 selection:bg-blue-600/30`}>
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView}
        darkMode={darkMode}
        setDarkMode={setDarkMode}
        points={points}
        streak={streak}
      />

      <main className="flex-1 overflow-y-auto h-screen relative scrollbar-thin scroll-smooth">
        {/* Floating Night Review Trigger */}
        {currentDayData && !currentDayData.completed && (
          <motion.div 
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="fixed bottom-10 right-10 z-[60]"
          >
             <button 
               onClick={() => setShowNightReviewModal(true)}
               className="group px-8 py-5 rounded-[2.5rem] bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 text-white font-black text-xs uppercase tracking-[0.2em] shadow-[0_20px_50px_rgba(59,130,246,0.5)] active:scale-95 transition-all flex items-center gap-4 hover:shadow-[0_0_30px_rgba(59,130,246,0.8)] border border-white/20"
             >
               <Moon size={20} className="group-hover:rotate-12 transition-transform" /> 
               Submit Night Review
             </button>
          </motion.div>
        )}

        <div className="pb-40">
          {renderView()}
        </div>
      </main>

      {/* Modals */}
      <AnimatePresence>
        {showNightReviewModal && currentDayData && (
          <NightReview 
            dayData={currentDayData}
            onClose={() => setShowNightReviewModal(false)}
            onComplete={(note, plan) => {
              completeDay(currentDay, note, plan);
              setShowNightReviewModal(false);
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;
